:root {
  --bg: #2d1b3d;
  --card-bg: #3e2a5c;
  --text: #f0e6ff;
  --accent: #b388ff;
  --accent-hover: #d1b3ff;
  --hunger-color: #ff6b6b;
  --happiness-color: #ffd93d;
  --energy-color: #6bcb77;
  --bar-bg: #1e1230;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
}

h1 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.pet-container {
  width: 160px;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 16px;
  padding: 8px;
}

.pet {
  width: 120px;
  height: 120px;
  position: relative;
  image-rendering: pixelated;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: #ffb347;
  border-radius: 24px 24px 16px 16px;
  position: relative;
  box-shadow:
    -8px -8px 0 0 #ffb347,
    8px -8px 0 0 #ffb347,
    -8px 8px 0 0 #ffb347,
    8px 8px 0 0 #ffb347,
    0 0 0 8px #e6952e;
  transition: transform 0.2s;
}

.pet-body::after {
  content: '';
  position: absolute;
  bottom: -16px;
  left: 50%;
  transform: translateX(-50%);
  width: 40px;
  height: 16px;
  background: #e6952e;
  border-radius: 0 0 8px 8px;
}

.pet-eye {
  position: absolute;
  width: 16px;
  height: 16px;
  background: #2d1b3d;
  border-radius: 4px;
  top: 40px;
}

.pet-eye.left {
  left: 28px;
}

.pet-eye.right {
  right: 28px;
}

.pet-mouth {
  position: absolute;
  width: 24px;
  height: 8px;
  background: #2d1b3d;
  border-radius: 0 0 8px 8px;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
}

.pet.sleeping .pet-eye {
  height: 4px;
  top: 46px;
  border-radius: 2px;
}

.pet.sleeping .pet-mouth {
  width: 16px;
  height: 4px;
  border-radius: 4px;
}

.pet.happy .pet-mouth {
  width: 32px;
  height: 16px;
  border-radius: 0 0 16px 16px;
  bottom: 24px;
}

.pet.sad .pet-mouth {
  width: 24px;
  height: 8px;
  border-radius: 8px 8px 0 0;
  bottom: 24px;
}

.mood {
  font-size: 18px;
  font-weight: 600;
  color: var(--accent-hover);
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 14px;
  font-weight: 600;
  opacity: 0.9;
}

.bar-bg {
  width: 100%;
  height: 16px;
  background: var(--bar-bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger {
  background: var(--hunger-color);
}

.bar-fill.happiness {
  background: var(--happiness-color);
}

.bar-fill.energy {
  background: var(--energy-color);
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

button {
  font-family: inherit;
  font-size: 16px;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 100px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 16px;
  }
  button {
    padding: 10px 16px;
    min-width: 80px;
  }
  .pet-container {
    width: 140px;
    height: 140px;
  }
  .pet {
    width: 100px;
    height: 100px;
  }
  .pet-body {
    border-radius: 20px 20px 14px 14px;
    box-shadow:
      -6px -6px 0 0 #ffb347,
      6px -6px 0 0 #ffb347,
      -6px 6px 0 0 #ffb347,
      6px 6px 0 0 #ffb347,
      0 0 0 6px #e6952e;
  }
  .pet-eye {
    width: 12px;
    height: 12px;
    top: 32px;
  }
  .pet-eye.left {
    left: 22px;
  }
  .pet-eye.right {
    right: 22px;
  }
  .pet-mouth {
    width: 20px;
    height: 6px;
    bottom: 26px;
  }
}

const state = {
  hunger: 100,
  happiness: 100,
  energy: 100
};

const petEl = document.getElementById('pet');
const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  petEl.classList.remove('happy', 'sad', 'sleeping');

  let mood = 'Happy';
  if (state.energy < 20) {
    mood = 'Sleepy';
    petEl.classList.add('sleeping');
  } else if (state.hunger < 20) {
    mood = 'Hungry';
    petEl.classList.add('sad');
  } else if (state.happiness < 20) {
    mood = 'Sad';
    petEl.classList.add('sad');
  } else if (state.hunger > 70 && state.happiness > 70 && state.energy > 70) {
    mood = 'Happy';
    petEl.classList.add('happy');
  } else {
    mood = 'Okay';
  }

  moodEl.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

setInterval(() => {
  state.hunger = clamp(state.hunger - 1);
  state.happiness = clamp(state.happiness - 1);
  state.energy = clamp(state.energy - 1);
  updateUI();
}, 5000);

updateUI();
